pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint128 amt) public {
        // keep amount in a sensible range and non-zero to trigger observable change
        uint256 amount = uint256(amt);
        vm.assume(depositor != address(0));
        vm.deal(depositor, amount);

        // observe pre-balance for depositor
        uint256 before = c.balances(depositor);

