        } else {
            // if Deposit reverted, the reference still ensures revert for invalid conditions;
            // we do not assert on state in that case, but the fuzzer can still find cases where
            // the mutant behaves differently for some inputs where ok==true.
            assertTrue(true);
        }
    }
