pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor will be a contract (Attacker) address, targetKey is any address whose balance we check,
    // amount is the deposit value. We deploy an Attacker contract that forwards a call to c.Deposit via a contract call
    // so msg.sender to c is the Attacker contract (not an EOA). This distinguishes behavior if mutant overwrites storage
    // for the contract-sender slot.
    function testFuzz_property(address targetKey, uint256 amount) public {
        // keep amount in a reasonable range to avoid trivial zero-value cases and extremely large values
        amount = bound(amount, 1, 1 ether);

        // fund an external EOA that will be used to call the Attacker so it can send ETH
        address user = address(0xABCD);
        vm.deal(user, 2 ether);

        // set up: give targetKey a nonzero balance in the reference contract
        // we simulate this by having targetKey deposit directly (as an EOA)
        // fund targetKey and have it deposit
        vm.deal(targetKey, 1 ether);
        vm.prank(targetKey);
        c.Deposit{value: 1 ether}();

        // record the balance of targetKey in the reference contract before the attacker's deposit
        uint256 before = c.balances(targetKey);

        // deploy an Attacker contract that will call c.Deposit forwarding the ETH it receives
        Attacker atk = new Attacker(address(c));

        // have user send ETH to Attacker and cause it to call c.Deposit from the Attacker contract
        vm.prank(user);
        (bool sent, ) = address(atk).call{value: amount}("run");
        require(sent);

        // After the Attacker (a contract) called c.Deposit, the reference must preserve other addresses' balances.
        // The mutant that writes balances[msg.sender] = msg.value may overwrite storage in unexpected ways when msg.sender
        // is a contract; thus we assert that targetKey's balance is unchanged.
        uint256 after = c.balances(targetKey);

        assertTrue(after == before);
    }
}

// Minimal adversarial helper: forwards received ETH to C.Deposit by calling deposit as a contract (so msg.sender==this contract)
contract Attacker {
    C public c;
    constructor(address _c) {
        c = C(_c);
    }
    // This contract receives a call with calldata "run" and value; it then calls c.Deposit forwarding the ETH.
    fallback() external payable {
        // call C.Deposit so that msg.sender inside C is this contract
        c.Deposit{value: msg.value}();
    }
}

