            assertTrue(c.balances(depositor) == beforeBal);
            assertTrue(address(c).balance == beforeContract);
            return;
        }

        // After a successful deposit, the real ether held by the contract must have increased by exactly amt
        uint256 afterContract = address(c).balance;
        // And the recorded balances for depositor must have increased by exactly the same amount
        // This holds for the reference but fails when balances are double-incremented.
        assertTrue(c.balances(depositor) - beforeBal == afterContract - beforeContract);
    }
