contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address and value to set. The general rule: after a successful SetMinSum(_val),
    // c.MinSum() == _val for the correct contract for all inputs. The mutant may break this for some inputs.
    function testFuzz_property(address caller, uint256 val) public {
        // keep caller non-zero (EOA) to be a valid caller; allow any val including 0.
        vm.assume(caller != address(0));

        // Ensure caller has some ETH so that if SetMinSum or any other call needed value it wouldn't fail due to lack of balance.
        vm.deal(caller, 1 ether);

        bool ok;
        // call SetMinSum as 'caller'
        vm.prank(caller);
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if the call returned normally (ok == true), then MinSum getter equals val.
        // The correct contract satisfies: for all caller and val, if SetMinSum(val) does not revert, then MinSum == val.
        // The mutant can make SetMinSum behave differently and thus this assertion will fail for some inputs on the mutant.
        assertTrue(!ok || c.MinSum() == val);
    }
}

