pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: the value to set as MinSum. The adversarial counterparty
    // is a deployed reentrant helper below; we will call SetLogFile to point
    // c at the helper and then invoke SetMinSum via the helper reentering.
    function testFuzz_property(uint256 val) public {
        // keep domain wide but avoid trivial overflow edges for block.timestamp uses
        // (no tight assumptions so the fuzzer can find failing val)
        // Deploy helper that will re-enter during SetMinSum by using SetLogFile then triggering AddMessage
        ReentrantHelper helper = new ReentrantHelper(address(c));

        // Point contract's Log to the helper (allowed before initialization)
        c.SetLogFile(address(helper));

        // Now call SetMinSum as the helper's address so that when c calls Log.AddMessage
        // (which happens in Deposit/Collect normally), our helper can reenter if needed.
        // But SetMinSum itself doesn't call Log; however the mutant flips intitalized=true
        // earlier, enabling the helper (via external calls) to detect initialized state
        // during subsequent interactions. To ensure the helper gets a chance, we have the helper
        // attempt a reentrant call into c.SetMinSum if it detects initialized==true.

        // The helper will attempt to call SetMinSum with the same val when it notices intitalized.
        // Call SetMinSum originally from this test (EOA). We capture success and then assert
        // that on the reference implementation MinSum equals val.

        bool ok;
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: on the correct contract, calling SetMinSum when not yet initialized
        // should succeed and set MinSum to the provided value. We assert that MinSum equals val.
        // This assertion must hold for the reference for all admissible val, and the mutant will
        // for some val (and reentrant interaction) produce a differing MinSum.
        assertTrue(ok && c.MinSum() == val);
    }
}

// Adversarial helper: if during any call it observes c.intitalized()==true (no getter exists for
// internal bool, but the mutant's earlier side-effect may cause reentrancy to affect subsequent
// interactions). We cannot read internal state; however we can attempt to reenter unconditionally
// to create a timing/interleaving that the mutant can exploit. This helper simply tries to call
// SetMinSum on the target contract when it receives any call.
contract ReentrantHelper {
    address target;
    bool reentered;
    constructor(address _t) {
        target = _t;
    }
    // receive will be invoked if contract is sent Ether; also fallback will be invoked on external calls
    fallback() external payable {
        // Guard to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // attempt to reenter SetMinSum with a different value (e.g., 0) to disturb state
            // Use low-level call to avoid revert bubbling
            (bool s, ) = target.call(abi.encodeWithSignature("SetMinSum(uint256)", 0));
            // ignore return
            s;
        }
    }
}

