import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameter: an arbitrary uint value to set as MinSum.
    // We'll also fuzz an address that will be used to deploy and act as the adversarial helper.
    function testFuzz_property(uint256 val, address helperDeployer) public {
        // Keep domains wide but reasonable: helperDeployer must be non-zero to deploy helper.
        vm.assume(helperDeployer != address(0));

        // Deploy an adversarial helper from the fuzzed deployer address. The helper's behavior:
        // when it receives AddMessage calls from LogFile it will, on first notification, call back
        // into C.SetMinSum again reentrantly. This simulates an external party reacting to the
        // momentary flip of intitalized in the mutant ordering.

        // fund deployer so it can create contracts
        vm.deal(helperDeployer, 1 ether);
        vm.startPrank(helperDeployer);
        ReentrantHelper h = new ReentrantHelper(address(c));
        vm.stopPrank();

        // Point C's Log to the helper so that when C does Log.AddMessage it will hit our helper.
        // Use arbitrary caller to perform SetLogFile; use the same helperDeployer as actor.
        vm.startPrank(helperDeployer);
        c.SetLogFile(address(h));
        vm.stopPrank();

        // Now call SetMinSum with fuzzed val. On the reference contract, after return, MinSum == val.
        // The mutant that sets intitalized = true before MinSum = _val may allow the helper's reentrant
        // behavior (triggered from Log.AddMessage on some other flows) to interfere and leave
        // MinSum != val for some inputs; the fuzzer should find such.

        // Call SetMinSum from an EOA (fuzzer actor). Use a non-zero address to be realistic.
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(val, helperDeployer)))));
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        bool ok;
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: on the correct contract the call should succeed and MinSum == val.
        // We assert that either the call reverted (ok == false) OR the stored MinSum equals val.
        // For the reference contract, for any fresh contract and any val the call will succeed and
        // MinSum == val, so the predicate below is always true. The mutant can make it false for
        // some fuzzed inputs (it may succeed but leave a different MinSum), which the fuzzer will find.
        assertTrue(!ok || c.MinSum() == val);
    }
}

// Minimal adversarial helper that will react when its AddMessage is called by the LogFile.
// It calls back into C.SetMinSum(reentrantValue) once the first time it is invoked.
contract ReentrantHelper {
    address public target;
    bool public called;

    constructor(address _target) payable {
        target = _target;
        called = false;
    }

    // This function will be called by LogFile.AddMessage (which is public). We mimic that
    // signature so the LogFile's call will hit this contract. On first invocation we reenter
    // and call SetMinSum with some value (e.g., 0) to perturb state during the parent call.
    // Keep the reentrant value simple and deterministic.
    function AddMessage(address, uint, string memory) public {
        if (!called) {
            called = true;
            // Reenter C.SetMinSum with a different value (e.g., 0) to try to disturb mutant ordering.
            // We don't use vm.prank here; this call originates from the LogFile invocation, so it's
            // a legitimate external call from this helper contract to C.
            try C(target).SetMinSum(0) {
                // ignore
            } catch {
                // ignore
            }
        }
    }
}

