// Helper that reverts on any AddMessage call (models a hostile external callee)
contract ReverterLog {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    // match signature: AddMessage(address,uint,string)
    function AddMessage(address, uint, string memory) public {
        revert("boom");
    }
}

// Benign logger that accepts messages
contract BenignLog {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

